def status(work, staged, head):
    to_commit = []
    not_staged = []
    untracked = []
    for name in set(staged) | set(head):
        if staged.get(name) != head.get(name):
            to_commit.append(name)
    for name in staged:
        if work.get(name) != staged[name]:
            not_staged.append(name)
    for name in work:
        if name not in staged:
            untracked.append(name)
    return {"staged": sorted(to_commit), "unstaged": sorted(not_staged), "untracked": sorted(untracked)}
